            if (tONTransactionMessage.ValueOption.IsSet)
                writer.WriteString("value", tONTransactionMessage.Value);

            if (tONTransactionMessage.ValueExtraCurrenciesOption.IsSet)
            {
                writer.WritePropertyName("valueExtraCurrencies");
                JsonSerializer.Serialize(writer, tONTransactionMessage.ValueExtraCurrencies, jsonSerializerOptions);
            }
        }
    }
}
